from pathlib import Pathimport jsonimport osimport requests# PathPROJECT_ROOT = Path(__file__).resolve().parent.parentRAW_DATA_DIR = (    PROJECT_ROOT    / "data"    / "raw")RAW_DATA_DIR.mkdir(    parents=True,    exist_ok=True,)OUTPUT_FILE = (    RAW_DATA_DIR    / "cirbe_2024_gp_history.json")# Space-Track settingsLOGIN_URL = (    "https://www.space-track.org/ajaxauth/login")BASE_QUERY_URL = (    "https://www.space-track.org/basicspacedata/query")# CIRBE satelliteNORAD_ID = 56188# May 2024 geomagnetic stormSTART_DATE = "2024-04-01"END_DATE = "2024-06-30"def get_credentials():    username = os.getenv(        "SPACETRACK_USERNAME"    )    password = os.getenv(        "SPACETRACK_PASSWORD"    )    if not username or not password:        raise ValueError(            "\nSpace-Track credentials were not found.\n\n"            "Set these environment variables first:\n"            "SPACETRACK_USERNAME\n"            "SPACETRACK_PASSWORD\n"        )    return username, password# Logindef login_to_spacetrack(    session,    username,    password,):    print(        "Logging into Space-Track..."    )    response = session.post(        LOGIN_URL,        data={            "identity": username,            "password": password,        },        timeout=30,    )    response.raise_for_status()    if not session.cookies:        raise RuntimeError(            "Space-Track login may have failed. "            "No session cookies were returned."        )    print(        "Space-Track login request completed."    )# Download CIRBE GP historydef download_gp_history(session):    """    Download historical orbital elements    for CIRBE (NORAD 56188).    """    print(        "\nDownloading CIRBE orbital history..."    )    query_url = (        f"{BASE_QUERY_URL}"        f"/class/gp_history"        f"/NORAD_CAT_ID/{NORAD_ID}"        f"/EPOCH/{START_DATE}--{END_DATE}"        f"/orderby/NORAD_CAT_ID%20asc,EPOCH%20asc"        f"/format/json"    )    response = session.get(        query_url,        timeout=120,    )    if response.status_code == 401:        raise RuntimeError(            "\nSpace-Track returned 401 Unauthorized.\n"            "The historical-data request was rejected.\n"            "Check whether this session is authenticated "            "and has GP_HISTORY access."        )    response.raise_for_status()    try:        records = response.json()    except requests.exceptions.JSONDecodeError:        print(            "\nSpace-Track did not return valid JSON."        )        print(            response.text[:1000]        )        raise    if not isinstance(records, list) or not records:        raise ValueError(            "Space-Track returned no CIRBE GP history "            "for the requested date range."        )    print(        f"Downloaded {len(records)} "        f"orbital records."    )    return recordsdef summarize_records(records):    print(        "\n-----------------------------------"    )    print(        "CIRBE 2024 ORBITAL DATA"    )    print(        "-----------------------------------"    )    print(        f"\nTotal orbital records: {len(records)}"    )    objects = {}    for record in records:        norad_id = record.get(            "NORAD_CAT_ID"        )        object_name = record.get(            "OBJECT_NAME"        )        object_id = record.get(            "OBJECT_ID"        )        if norad_id not in objects:            objects[norad_id] = {                "object_name": object_name,                "object_id": object_id,            }    for norad_id, info in objects.items():        print(            f"\nNORAD ID: {norad_id}"        )        print(            f"Satellite name: {info['object_name']}"        )        print(            f"Object ID: {info['object_id']}"        )    epochs = sorted(        record["EPOCH"]        for record in records        if record.get("EPOCH")    )    if epochs:        print(            f"\nFirst orbital record: {epochs[0]}"        )        print(            f"Last orbital record: {epochs[-1]}"        )def save_records(records):    with open(        OUTPUT_FILE,        "w",        encoding="utf-8",    ) as file:        json.dump(            records,            file,            indent=2,        )    print(        f"\nSaved CIRBE orbital history to:\n"        f"{OUTPUT_FILE}"    )# Maindef main():    username, password = (        get_credentials()    )    with requests.Session() as session:        login_to_spacetrack(            session,            username,            password,        )        records = download_gp_history(            session        )    summarize_records(        records    )    save_records(        records    )    print(        "\nCIRBE download complete!"    )if __name__ == "__main__":    main()